/bin/zsh -lc "python3 -B - <<'PY'
import sqlite3
from contextlib import closing

with closing(sqlite3.connect(':memory:')) as con:
    active = set()
    con.create_function('_allowed', 1, lambda name: int(name not in active))
    con.create_function('_enter', 1, lambda name: active.add(name))
    con.create_function('_leave', 1, lambda name: active.discard(name))
    con.executescript('''
        CREATE TABLE accounts(tenant TEXT, name TEXT, balance INTEGER,
                              PRIMARY KEY(tenant,name));
        INSERT INTO accounts VALUES ('one','a',100),('two','private',900);
        CREATE UNIQUE INDEX amount_unique ON accounts(balance);
        CREATE TEMP TABLE delta(tenant, name, balance, n);
        CREATE TEMP TRIGGER observed_insert AFTER INSERT ON main.accounts
        BEGIN INSERT INTO delta VALUES(NEW.tenant,NEW.name,NEW.balance,1); END;
        CREATE TEMP TRIGGER observed_delete AFTER DELETE ON main.accounts
        BEGIN INSERT INTO delta VALUES(OLD.tenant,OLD.name,OLD.balance,-1); END;
        CREATE TEMP TRIGGER observed_update AFTER UPDATE ON main.accounts
        BEGIN
          INSERT INTO delta VALUES(OLD.tenant,OLD.name,OLD.balance,-1);
          INSERT INTO delta VALUES(NEW.tenant,NEW.name,NEW.balance,1);
        END;
        PRAGMA recursive_triggers=ON;
        CREATE TRIGGER 审核 AFTER UPDATE ON accounts
        WHEN CASE WHEN _allowed(1) THEN (NEW.tenant='one') ELSE 0 END
        BEGIN
          SELECT _enter(1);
          UPDATE accounts SET balance=balance WHERE tenant=NEW.tenant AND name=NEW.name;
          SELECT _leave(1);
        END;
    ''')
    for policy, expected_valid in [('IGNORE', True), ('REPLACE', False)]:
        con.execute('SAVEPOINT probe')
        con.execute(\"UPDATE accounts SET balance=90 WHERE tenant='one' AND name='a'\")
        con.execute('INSERT OR ' + policy + \" INTO accounts VALUES ('one','extra',900)\")
        con.execute(\"INSERT INTO delta VALUES ('one','a',100,1),('one','a',90,-1)\")
        valid = not con.execute('SELECT EXISTS(SELECT 1 FROM delta GROUP BY tenant,name,balance HAVING SUM(n)<>0)').fetchone()[0]
        assert valid == expected_valid, (policy, valid)
        assert not active
        con.execute('ROLLBACK TO probe')
        con.execute('RELEASE probe')
        print(policy, 'allowed expected logical delta =', valid)
    print('Observer/guard proof passed: successful effects, implicit deletion, and nonrecursive no-op control')
PY"

